mod solution;

fn main() {
    let cases = [
    (r#"n=5 updates=(0,2,2),(1,3,3),(3,4,1)"#, r#"4"#),
    (r#"n=4 updates=(0,1,2),(1,3,1)"#, r#"3"#),
    (r#"
n=4 updates=(0,1,2),(1,3,1)
"#, r#"3"#),
    (r#"  
n=5 updates=(0,2,2),(1,3,3),(3,4,1)
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS imos-sweep");
}
